#sheet-amber .sh-btn.secondary{background:#F2F2F7;color:#1C1C1E}
#countdown{position:absolute;inset:0;z-index:48;display:none;flex-direction:column;align-items:center;justify-content:center;gap:24px;background:rgba(12,12,14,.8);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);color:#fff}
