#cntdwn-num{position:absolute;inset:0;display:grid;place-items:center;font-size:64px;font-weight:600;font-variant-numeric:tabular-nums}
#cntdwn-txt{font-size:19px;line-height:1.35;text-align:center;padding:0 48px}
