.al-msg{padding:20px 18px 18px;font-size:17px;font-weight:600;line-height:1.3}
.al-box button{display:block;width:100%;height:48px;border-top:1px solid rgba(60,60,67,.24);color:var(--ios-blue);font-size:17px}
.al-box button.b{font-weight:600}
#banner{position:absolute;left:8px;right:8px;top:56px;z-index:56;display:flex;gap:10px;align-items:center;padding:12px 14px;border-radius:24px;
  background:rgba(246,246,248,.92);-webkit-backdrop-filter:blur(24px);backdrop-filter:blur(24px);box-shadow:0 8px 24px rgba(0,0,0,.18);
